local function isNPCModel(model)
    if not model or not model:IsA("Model") then return false end
    if excusemesir.Players:GetPlayerFromCharacter(model) then return false end
    local humanoid = model:FindFirstChildOfClass("Humanoid")
    if humanoid and humanoid.Health ~= nil then
        if model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Head") then
            return true
        end
    end
    return false
end

do
    local WS = workspace
    local set, list = {}, {}
    local function consider(inst)
        if inst:IsA("Humanoid") then
            local m = inst.Parent
            if m and m:IsA("Model") then set[m] = true end
        end
    end
    WS.DescendantAdded:Connect(consider)
    WS.DescendantRemoving:Connect(function(inst)
        if inst:IsA("Humanoid") then
            local m = inst.Parent
            if m then set[m] = nil end
        end
    end)
    task.spawn(function()
        local n = 0
        for _, d in ipairs(WS:GetDescendants()) do
            consider(d)
            n = n + 1
            if n % 2000 == 0 then task.wait() end
        end
    end)
    config.getNPCModels = function()
        table.clear(list)
        for m in pairs(set) do
            if m.Parent then
                if isNPCModel(m) then list[#list + 1] = m end
            else
                set[m] = nil
            end
        end
        return list
    end
end

