local saveConfig, deleteSave, deleteAllSaves, loadSave, SETDAAUTOLAOD_, nullifymahfilez_,
      autolaodbssthing_, startdaautlado_
do
local function getSavePath(saveName)
    return getgenv().blablablahblahblahhblahblahhGraaaaaaaaaaaaaaaaaaaaaaaveel_.Folder .. "/" .. saveName .. getgenv().blablablahblahblahhblahblahhGraaaaaaaaaaaaaaaaaaaaaaaveel_.Extension
end

local function getSaveList()
    local saves = {}
    if not isfolder(getgenv().blablablahblahblahhblahblahhGraaaaaaaaaaaaaaaaaaaaaaaveel_.Folder) then
        return saves
    end
    
    for _, file in ipairs(listfiles(getgenv().blablablahblahblahhblahblahhGraaaaaaaaaaaaaaaaaaaaaaaveel_.Folder)) do
        local fileName = file:match("([^/]+)" .. getgenv().blablablahblahblahhblahblahhGraaaaaaaaaaaaaaaaaaaaaaaveel_.Extension .. "$")
        if fileName then
            table.insert(saves, fileName)
        end
    end
    return saves
end

local function loadSaveData(saveName)
    local path = getSavePath(saveName)
    if not isfile(path) then
        return nil
    end
    
    local success, data = pcall(function()
        return readfile(path)
    end)
    
    if not success or not data then
        return nil
    end
    
    local success, decoded = pcall(function()
        return game:GetService("HttpService"):JSONDecode(data)
    end)
    
    return success and decoded or nil
end

local function fuzzymatch(inputName)
    if not inputName or inputName == "" then
        return nil, "Please enter a save name"
    end
    
    local saves = getSaveList()
    if #saves == 0 then
        return nil, "No saves found"
    end
    local inputLower = string.lower(inputName)
    local function getSimilarity(str1, str2)
        local s1 = string.lower(str1)
        local s2 = string.lower(str2)
        if s1 == s2 then
            return 1.0
        end
        if string.find(s2, s1, 1, true) then
            return 1.0 - (string.len(s2) - string.len(s1)) * 0.01
        end
        
        if string.find(s1, s2, 1, true) then
            return 1.0 - (string.len(s1) - string.len(s2)) * 0.01
        end
        
        local function levenshtein(a, b)
            local lenA, lenB = #a, #b
            local matrix = {}
            
            for i = 0, lenA do
                matrix[i] = {}
                matrix[i][0] = i
            end
            
            for j = 0, lenB do
                matrix[0][j] = j
            end
            
            for i = 1, lenA do
                for j = 1, lenB do
                    local cost = (a:sub(i, i) == b:sub(j, j)) and 0 or 1
                    matrix[i][j] = math.min(
                        matrix[i-1][j] + 1,
                        matrix[i][j-1] + 1,
                        matrix[i-1][j-1] + cost
                    )
                end
            end
            
            return matrix[lenA][lenB]
        end
        
        local maxLen = math.max(#s1, #s2)
        if maxLen == 0 then return 0 end
        local distance = levenshtein(s1, s2)
        local similarity = 1 - (distance / maxLen)
        local prefixLen = 0
        for i = 1, math.min(#s1, #s2) do
            if s1:sub(i, i) == s2:sub(i, i) then
                prefixLen = prefixLen + 1
            else
                break
            end
        end
        
        if prefixLen > 0 then
            local prefixBoost = (prefixLen / math.min(#s1, #s2)) * 0.1
            similarity = math.min(similarity + prefixBoost, 1.0)
        end
        
        return similarity
    end
    local scored = {}
    for _, save in ipairs(saves) do
        local similarity = getSimilarity(inputLower, save)
        table.insert(scored, {
            name = save,
            similarity = similarity
        })
    end
    table.sort(scored, function(a, b)
        if a.similarity == b.similarity then
            return #a.name < #b.name
        end
        return a.similarity > b.similarity
    end)
    local best = scored[1]
    local threshold = 0.6
    
    if best.similarity < threshold then
        return nil, "No saves found matching '" .. inputName .. "'"
    end
    local exactMatch = false
    local similarMatches = {}
    
    for _, item in ipairs(scored) do
        if item.similarity >= 0.8 then
            if string.lower(item.name) == inputLower then
                exactMatch = true
                table.insert(similarMatches, item.name)
            else
                table.insert(similarMatches, item.name)
            end
        end
    end
    if exactMatch then
        return similarMatches[1] or inputName, nil
    end
    
    if #similarMatches > 1 then
        return best.name, nil
    elseif #similarMatches == 1 then
        return similarMatches[1], nil
    else
        if best.similarity >= 0.7 then
            return best.name, nil
        else
            return nil, "No saves found matching '" .. inputName .. "'"
        end
    end
end
