function uhhhhgetnamesbetter(saveName)
    if not saveName or saveName == "" then return nil end
    local saves = getSaveList()
    for _, s in ipairs(saves) do
        if s == saveName then return s end
    end
    local lower = string.lower(saveName)
    for _, s in ipairs(saves) do
        if string.lower(s) == lower then return s end
    end
    return nil
end
function savePara()
    local saves = getSaveList()
    local saveText = "Available Saves:\n"
    
    if #saves == 0 then
        saveText = saveText .. "  There isn't any saves 💔??"
    else
        for i, save in ipairs(saves) do
            local isCurrent = (save == getgenv().blablablahblahblahhblahblahhGraaaaaaaaaaaaaaaaaaaaaaaveel_.CurrentSave)
            saveText = saveText .. "  " .. (isCurrent and "✓ " or "> ") .. save .. (isCurrent and "!" or "") .. "\n"
        end
    end
    
    return saveText
end

