config.varibz.raycats.rayowo.IgnoreWater = true
config.varibz.raycats.ihazrays.FilterType = Enum.RaycastFilterType.Exclude
config.varibz.raycats.ihazrays.IgnoreWater = true

local function IsPlayerVisible(player, maxDistance)
    local isPlayer = typeof(player) == "Instance" and player:IsA("Player")
    local isModel = typeof(player) == "Instance" and player:IsA("Model")
    if not isPlayer and not isModel then return false end
    local PlayerCharacter
    if isPlayer then
        PlayerCharacter = player.Character
    else
        PlayerCharacter = player
    end
    if not PlayerCharacter then return false end
    local LocalPlayerCharacter = plr.Character
    if not LocalPlayerCharacter then return false end
    local PlayerRoot = PlayerCharacter:FindFirstChild("HumanoidRootPart") or PlayerCharacter:FindFirstChild("Head")
    if not PlayerRoot then return false end
    local LocalRoot = LocalPlayerCharacter:FindFirstChild("Head") or LocalPlayerCharacter:FindFirstChild("HumanoidRootPart")
    if not LocalRoot then return false end
    local origin = LocalRoot.Position
    local targetPos = PlayerRoot.Position
    local dir = targetPos - origin
    local distance = dir.Magnitude
    if maxDistance and distance > maxDistance then return false end
    if distance < 0.1 then return true end
    local now = tick()
    if now - config.varibz.sa2dump.flt > 0.25 then
        local list = {LocalPlayerCharacter, PlayerCharacter}
        for _, proxyPart in pairs(config.proxyHitboxes) do
            if proxyPart and proxyPart.Parent then
                table.insert(list, proxyPart)
            end
        end
        for playerKey, data in pairs(config.hitboxExpandedParts) do
            if data and data.part and data.part.Parent then
                table.insert(list, data.part)
            end
        end
        config.varibz.sa2dump.flist = list
        config.varibz.sa2dump.flt = now
    end
    if not config.varibz.raycats.raycat then
        config.varibz.raycats.raycat = RaycastParams.new()
        config.varibz.raycats.raycat.FilterType = Enum.RaycastFilterType.Exclude
        config.varibz.raycats.raycat.IgnoreWater = true
    end
    config.varibz.raycats.raycat.FilterDescendantsInstances = config.varibz.sa2dump.flist
    local result = workspace:Raycast(origin, dir.Unit * distance, config.varibz.raycats.raycat)
    if not result then return true end
    local hitInstance = result.Instance
    local hitParent = hitInstance and hitInstance.Parent
    if hitParent == PlayerCharacter or (hitParent and hitParent.Parent == PlayerCharacter) then
        return true
    end
    if hitInstance == PlayerCharacter then
        return true
    end
    return false
end
config.Priority = (function()
    local P = {}
    local Players = excusemesir.Players
    local UIS = excusemesir.UserInputService
    local clock = os.clock
    local huge = math.huge
    P.Modes = {
        "Closest", "Farthest", "Lowest Health", "Highest Health", "Lowest Health %",
        "Closest To Crosshair", "Closest To Cursor", "Aim At You", "Holding Tool",
        "TargetSeen", "Stick To Target"
    }
    local valid = {}
    for _, m in ipairs(P.Modes) do valid[m] = true end
    local stickybonus = 0.2
    local aimhalflife = 0.75
    local aimconecos = math.cos(math.rad(30))
    local toolTTL = 0.2
    function P.toList(sel)
        local out = {}
        if type(sel) == "string" then
            if valid[sel] then out[1] = sel end
        elseif type(sel) == "table" then
            for _, v in ipairs(sel) do
                if valid[v] and not table.find(out, v) then out[#out + 1] = v end
            end
        end
        if #out == 0 then out[1] = "Closest" end
        return out
    end

    function P.hasSeen(sel)
        if sel == "TargetSeen" then return true end
        if type(sel) == "table" then
            for _, v in ipairs(sel) do
                if v == "TargetSeen" then return true end
            end
        end
        return false
    end

    function P.hasRanking(sel)
        if type(sel) == "string" then
            return valid[sel] == true and sel ~= "TargetSeen" and sel ~= "Stick To Target"
        end
        if type(sel) == "table" then
            for _, v in ipairs(sel) do
                if valid[v] and v ~= "TargetSeen" and v ~= "Stick To Target" then return true end
            end
        end
        return false
    end

    local pools = {}
    local aimState = setmetatable({}, {__mode = "k"})
    local toolCache = setmetatable({}, {__mode = "k"})
    local lookSrcCache = setmetatable({}, {__mode = "k"})
    Players.PlayerRemoving:Connect(function(pl) aimState[pl] = nil end)
    local function getPool(key)
        local p = pools[key]
        if not p then
            p = {n = 0, items = {}, raw = {}, mins = {}, maxs = {}, invs = {}, ms = {}, fns = {}, ctx = {}, last = nil}
            pools[key] = p
        end
        return p
    end
    function P.begin(key)
        getPool(key).n = 0
    end
    function P.push(key, inst, char, hum, part, dist, ref)
        local p = getPool(key)
        local n = p.n + 1
        p.n = n
        local e = p.items[n]
        if not e then
            e = {}
            p.items[n] = e
        end
        e.inst, e.char, e.hum, e.part, e.dist, e.ref = inst, char, hum, part, dist, ref
        e.skip = false
        e.cc, e.hc = nil, nil
    end
    local function charOf(e)
        local c = e.cc
        if c == nil then
            c = e.char or getTargetCharacter(e.inst) or false
            e.cc = c
        end
        return c
    end
    local function humOf(e)
        local h = e.hum
        if h then return h end
        h = e.hc
        if h == nil then
            local c = charOf(e)
            h = c and c:FindFirstChildOfClass("Humanoid") or false
            e.hc = h
        end
        return h
    end
    local function holdingTool(char, now)
        local c = toolCache[char]
        if c and now - c.t < toolTTL then return c.v end
        if not c then c = {}; toolCache[char] = c end
        c.v = char:FindFirstChildOfClass("Tool") ~= nil
        c.t = now
        return c.v
    end
    local function lookSource(char)
        local s = lookSrcCache[char]
        if s and s.Parent then return s end
        s = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
        lookSrcCache[char] = s
        return s
    end
    local function angleMetric(origin, dir, part, blend)
        if not part then return nil end
        local v = part.Position - origin
        local mag = v.Magnitude
        if mag < 0.001 then return blend and 0 or -1 end
        local d = dir:Dot(v) / mag
        if not blend then return -d end
        if d > 1 then d = 1 elseif d < -1 then d = -1 end
        return math.acos(d)
    end

    local function aimAlignment(inst, char, ctx)
        if not char then return 0 end
        local src = lookSource(char)
        if not src then return 0 end
        local cf = src.CFrame
        local to = ctx.myPos - cf.Position
        local tx, tz = to.X, to.Z
        local tm = math.sqrt(tx * tx + tz * tz)
        if tm < 0.01 then return 1 end
        local look = cf.LookVector
        local lx, lz = look.X, look.Z
        local lm = math.sqrt(lx * lx + lz * lz)
        if lm < 0.01 then return 0 end
        local d = (lx * tx + lz * tz) / (lm * tm)
        local a = (d - aimconecos) / (1 - aimconecos)
        if a < 0 then a = 0 elseif a > 1 then a = 1 end
        local now = ctx.now
        local st = aimState[inst]
        if not st then
            st = {v = a, t = now}
            aimState[inst] = st
        else
            local dt = now - st.t
            if dt >= 0.03 then
                if dt > 1.5 then
                    st.v = a
                else
                    st.v = st.v + (a - st.v) * (1 - 0.5 ^ (dt / aimhalflife))
                end
                st.t = now
            end
        end
        return st.v
    end
    local M = {}
    M["Closest"] = function(e) return e.dist end
    M["Farthest"] = function(e)
        local d = e.dist
        return d and -d or nil
    end
    M["Lowest Health"] = function(e)
        local h = humOf(e)
        return h and h.Health or nil
    end
    M["Highest Health"] = function(e)
        local h = humOf(e)
        return h and -h.Health or nil
    end
    M["Lowest Health %"] = function(e)
        local h = humOf(e)
        return h and h.Health / math.max(h.MaxHealth, 1) or nil
    end
    M["Closest To Crosshair"] = function(e, ctx)
        return angleMetric(ctx.camPos, ctx.camLook, e.part, ctx.blend)
    end
    M["Closest To Cursor"] = function(e, ctx)
        return angleMetric(ctx.curOrigin, ctx.curDir, e.part, ctx.blend)
    end
    M["Aim At You"] = function(e, ctx)
        return -aimAlignment(e.inst, charOf(e), ctx)
    end
    M["Holding Tool"] = function(e, ctx)
        local c = charOf(e)
        return (c and holdingTool(c, ctx.now)) and 0 or 1
    end
    local function parseInto(ms, sel)
        local sticky = false
        if type(sel) == "string" then
            if sel == "Stick To Target" then
                sticky = true
            elseif valid[sel] and sel ~= "TargetSeen" then
                ms[1] = sel
            end
        elseif type(sel) == "table" then
            for _, v in ipairs(sel) do
                if v == "Stick To Target" then
                    sticky = true
                elseif v ~= "TargetSeen" and valid[v] then
                    local dup = false
                    for k = 1, #ms do
                        if ms[k] == v then dup = true break end
                    end
                    if not dup then ms[#ms + 1] = v end
                end
            end
        end
        return sticky
    end

    function P.resolve(key, sel, default, exclude)
        local p = getPool(key)
        local n = p.n
        local items = p.items
        if n == 0 then
            p.last = nil
            return nil
        end
        if n == 1 then
            local e = items[1]
            if exclude ~= nil and e.inst == exclude then
                p.last = nil
                return nil
            end
            p.last = e.inst
            return e.inst, e.ref
        end
        local ms, fns = p.ms, p.fns
        table.clear(ms)
        local sticky = parseInto(ms, sel)
        if #ms == 0 then ms[1] = default or "Closest" end
        local nm = #ms
        local needCursor = false
        for mi = 1, nm do
            fns[mi] = M[ms[mi]] or M["Closest"]
            if ms[mi] == "Closest To Cursor" then needCursor = true end
        end

        local ctx = p.ctx
        local cam = workspace.CurrentCamera
        local cf = cam.CFrame
        ctx.camPos, ctx.camLook = cf.Position, cf.LookVector
        ctx.curOrigin, ctx.curDir = ctx.camPos, ctx.camLook
        ctx.now = clock()
        ctx.blend = nm > 1
        local myChar = plr.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        ctx.myPos = myRoot and myRoot.Position or ctx.camPos
        if needCursor then
            local ml
            if config.fovEffectiveMode() == "Touch" then
                ml = config.getFovCenter(cam.ViewportSize)
            elseif UIS.MouseEnabled then
                ml = UIS:GetMouseLocation()
            end
            if ml then
                local ray = cam:ViewportPointToRay(ml.X, ml.Y)
                ctx.curOrigin, ctx.curDir = ray.Origin, ray.Direction.Unit
            end
        end
        local skip = (exclude ~= nil)
        if nm == 1 and not sticky then
            local fn = fns[1]
            local bestI, bestV, firstLive
            for i = 1, n do
                local e = items[i]
                if skip and e.inst == exclude then
                    e.skip = true
                else
                    e.skip = false
                    if not firstLive then firstLive = i end
                    local v = fn(e, ctx)
                    if v ~= nil and v == v and v ~= huge and v ~= -huge then
                        if bestV == nil or v < bestV then bestV, bestI = v, i end
                    end
                end
            end
            local pick = items[bestI or firstLive or 1]
            p.last = pick.inst
            return pick.inst, pick.ref
        end

        local raw, mins, maxs, invs = p.raw, p.mins, p.maxs, p.invs
        for mi = 1, nm do
            mins[mi], maxs[mi] = huge, -huge
            if not raw[mi] then raw[mi] = {} end
        end

        local live = 0
        for i = 1, n do
            local e = items[i]
            if skip and e.inst == exclude then
                e.skip = true
            else
                e.skip = false
                live = live + 1
                for mi = 1, nm do
                    local v = fns[mi](e, ctx)
                    if v == nil or v ~= v or v == huge or v == -huge then
                        v = false
                    else
                        if v < mins[mi] then mins[mi] = v end
                        if v > maxs[mi] then maxs[mi] = v end
                    end
                    raw[mi][i] = v
                end
            end
        end

        if live == 0 then
            p.last = items[1].inst
            return items[1].inst, items[1].ref
        end

        for mi = 1, nm do
            local range = maxs[mi] - mins[mi]
            invs[mi] = range > 1e-6 and (1 / range) or 0
        end

        local bestI, bestScore = nil, huge
        local last = p.last
        for i = 1, n do
            local e = items[i]
            if not e.skip then
                local sc = 0
                for mi = 1, nm do
                    local v = raw[mi][i]
                    if v == false then
                        sc = sc + 1
                    else
                        sc = sc + (v - mins[mi]) * invs[mi]
                    end
                end
                sc = sc / nm
                if sticky and last ~= nil and e.inst == last then
                    sc = sc - stickybonus
                end
                if sc < bestScore then
                    bestScore, bestI = sc, i
                end
            end
        end

        local best = items[bestI or 1]
        p.last = best.inst
        return best.inst, best.ref
    end

    function P.pickAnti(sel, list)
        P.begin("anti")
        for i = 1, #list do
            local e = list[i]
            P.push("anti", e.target, e.char, e.humanoid, e.root, e.distance, e)
        end
        local _, ref = P.resolve("anti", sel, "Closest")
        return ref
    end

    function P.pickAim(sel, list)
        P.begin("aim")
        for i = 1, #list do
            local e = list[i]
            P.push("aim", e.target, nil, e.humanoid, e.part, e.worldDist, e)
        end
        local _, ref = P.resolve("aim", sel, "Closest")
        return ref
    end

    function P.pickSilent(sel, list)
        P.begin("silent")
        for i = 1, #list do
            local e = list[i]
            P.push("silent", e.player, nil, e.humanoid, e.part, e.worldDist, e)
        end
        local _, ref = P.resolve("silent", sel, "Closest")
        return ref
    end

    function P.pickTbot(sel, list)
        P.begin("tbot")
        for i = 1, #list do
            local e = list[i]
            P.push("tbot", e.target, e.char, e.humanoid, e.part, e.worldDist, e)
        end
        local _, ref = P.resolve("tbot", sel, "Closest")
        return ref
    end

    return P
end)()

local function GetClosestPlayer()
    if not config.varibz.sa2this then
        return nil
    end
    if config.varibz.respawnLock or not plr.Character then
        config.SA2_currentTarget = nil
        return nil
    end
    local cam = Camera
    local viewport = cam.ViewportSize
    local camPos = cam.CFrame.Position
    local targetMode = config.masterGetTarget
    local seenMode = config.Priority.hasSeen(targetMode)
    local localTeam = plr.Team
    local center = config.getFovCenter(viewport)
    local maxRangeSq1 = config.SA2_TargetRange * config.SA2_TargetRange
    local character = plr.Character
    local localRoot = character and character:FindFirstChild("HumanoidRootPart")
    if not localRoot then
        config.SA2_currentTarget = nil
        return nil
    end
    local currentTime = tick()
    local shouldSwitch = (currentTime - config.lastTargetSwitchTime) >= config.targetSeenSwitchRate
    local useFOV = not config.SA2_ThreeSixtyMode
    local fovRadiusSq = config.SA2_FovRadius * config.SA2_FovRadius
    local bestTarget = nil
    local bestScore = nil
    local seenTargets = {}
    local lp = plr
    local candidates = config.varibz.candidates
    table.clear(candidates)
    if config.masterTarget == "Players" or config.masterTarget == "Both" then
        for _, p in ipairs(excusemesir.Players:GetPlayers()) do
            if p ~= lp and not config.isBlacklisted(p) then
                table.insert(candidates, {type = "player", instance = p})
            end
        end
    end
    if config.masterTarget == "NPCs" or config.masterTarget == "Both" then
        if currentTime - config.varibz.npcCache.lastRefresh > 1 then
            config.varibz.npcCache.lastRefresh = currentTime
            local newCache = {}
            for _, obj in ipairs(config.getNPCModels()) do
                table.insert(newCache, obj)
            end
            config.varibz.npcCache.list = newCache
        end
        for _, npc in ipairs(config.varibz.npcCache.list) do
            if npc and npc.Parent and isNPCModel(npc) then
                table.insert(candidates, {type = "npc", instance = npc})
            end
        end
    end
    if #candidates == 0 then
        config.SA2_currentTarget = nil
        return nil
    end
    if currentTime - config.varibz.sa2dump.lclr > config.varibz.sa2dump.t then
        local oldData = config.varibz.sa2dump.data
        local oldWall = config.varibz.sa2dump.cache
        local newData = {}
        local newWall = {}
        local cutoff = currentTime - 5
        for key, val in pairs(oldData) do
            if val.time and val.time > cutoff then
                newData[key] = val
            end
        end
        for key, val in pairs(oldWall) do
            if val.time and val.time > cutoff then
                newWall[key] = val
            end
        end
        config.varibz.sa2dump.data = newData
        config.varibz.sa2dump.cache = newWall
        config.varibz.sa2dump.lclr = currentTime
    end
    local validPlayers = config.varibz.sa2dump.validPlayers
    if not validPlayers then
        validPlayers = {}
        config.varibz.sa2dump.validPlayers = validPlayers
    end
    table.clear(validPlayers)
    local playerCount = 0
    config.Priority.begin("sa2")
    for _, candidate in ipairs(candidates) do
        local p = candidate.instance
        local isPlayer = (candidate.type == "player")
        if isPlayer then
            if config.specificTeamTarget and #config.targetedTeams > 0 then
                local team = p.Team
                local isTargeted = false
                if team then
                    for _, teamName in ipairs(config.targetedTeams) do
                        if team.Name == teamName then
                            isTargeted = true
                            break
                        end
                    end
                end
                if not isTargeted then
                    validPlayers[p] = false
                    continue
                end
            else
                if config.SA2_TeamTarget ~= "All" then
                    local targetTeam = p.Team
                    if not localTeam or not targetTeam then
                        if config.SA2_TeamTarget == "Teams" then
                            validPlayers[p] = false
                            continue
                        end
                    elseif config.SA2_TeamTarget == "Enemies" and localTeam == targetTeam then
                        validPlayers[p] = false
                        continue
                    elseif config.SA2_TeamTarget == "Teams" and localTeam ~= targetTeam then
                        validPlayers[p] = false
                        continue
                    end
                end
            end
        else
            if config.specificTeamTarget and #config.targetedTeams > 0 then
                local npcTeam = p:FindFirstChild("Team")
                local isTargeted = false
                if npcTeam and npcTeam:IsA("ObjectValue") and npcTeam.Value then
                    for _, teamName in ipairs(config.targetedTeams) do
                        if npcTeam.Value.Name == teamName then
                            isTargeted = true
                            break
                        end
                    end
                end
                if not isTargeted then
                    validPlayers[p] = false
                    continue
                end
            end
        end
        local char = getTargetCharacter(p)
        if char then
            local humanoid = char:FindFirstChildOfClass("Humanoid")
            if humanoid and humanoid.Health > 0 then
                if config.ignoreForcefield and hasForcefield(char) then
                    validPlayers[p] = false
                    continue
                end
                local rootPart = char:FindFirstChild("HumanoidRootPart")
                if rootPart then
                    local dx = rootPart.Position.X - localRoot.Position.X
                    local dy = rootPart.Position.Y - localRoot.Position.Y
                    local dz = rootPart.Position.Z - localRoot.Position.Z
                    local distSq = dx * dx + dy * dy + dz * dz
                    if distSq <= maxRangeSq1 then
                        local part = nil
                        local targetPartStr = config.SA2_TargetPart
                        if targetPartStr == "Random" then
                            if math.random(1, 100) <= config.SA2_HeadshotChance then
                                part = char:FindFirstChild("Head")
                            end
                            if not part then
                                part = char:FindFirstChild("HumanoidRootPart")
                            end
                            if not part then
                                part = char:FindFirstChild("Head")
                            end
                        else
                            part = char:FindFirstChild(targetPartStr)
                            if not part then
                                part = char:FindFirstChild("Head")
                            end
                        end
                        if part then
                            if config.SA2_Wallcheck then
                                local cacheKey
                                if isPlayer then
                                    cacheKey = "player_" .. tostring(p.UserId) .. "_" .. tostring(config.SA2_TargetRange)
                                else
                                    cacheKey = "npc_" .. tostring(p) .. "_" .. tostring(config.SA2_TargetRange)
                                end
                                local cached = config.varibz.sa2dump.cache[cacheKey]
                                local visible = false
                                if cached and (currentTime - cached.time) < 0.2 then
                                    visible = cached.visible
                                else
                                    visible = IsPlayerVisible(p, config.SA2_TargetRange)
                                    config.varibz.sa2dump.cache[cacheKey] = {
                                        visible = visible,
                                        time = currentTime
                                    }
                                end
                                if not visible then
                                    validPlayers[p] = false
                                    continue
                                end
                            end
                            validPlayers[p] = true
                            playerCount = playerCount + 1
                            seenTargets[p] = true
                            local worldDist = math.sqrt(distSq)
                            local inFOV = false
                            local screenDist = 0
                            if useFOV then
                                local fovPart = part
                                if targetPartStr == "Random" then
                                    fovPart = char:FindFirstChild("HumanoidRootPart") or part
                                end
                                local targetPos = fovPart.Position
                                local screenPos, onScreen = camera:WorldToViewportPoint(targetPos)
                                if onScreen and screenPos.Z > 0 then
                                    local distX = screenPos.X - center.X
                                    local distY = screenPos.Y - center.Y
                                    screenDist = distX * distX + distY * distY
                                    inFOV = screenDist <= fovRadiusSq
                                end
                            else
                                inFOV = true
                            end
                            if inFOV then
                                config.Priority.push("sa2", p, char, humanoid, part, worldDist)
                            end
                        else
                            validPlayers[p] = false
                        end
                    else
                        validPlayers[p] = false
                    end
                else
                    validPlayers[p] = false
                end
            else
                validPlayers[p] = false
            end
        else
            validPlayers[p] = false
        end
    end
    if playerCount == 0 then
        config.SA2_currentTarget = nil
        return nil
    end
    bestTarget = config.Priority.resolve("sa2", targetMode, seenMode and "Closest To Crosshair" or "Closest", seenMode and config.SA2_currentTarget or nil)
    local toRemove = {}
    for cacheKey in pairs(config.varibz.sa2dump.data) do
        local playerId = cacheKey:match("player_(%d+)")
        if playerId then
            playerId = tonumber(playerId)
            local isValid = false
            for p, valid in pairs(validPlayers) do
                if p and p.UserId == playerId and valid == true then
                    isValid = true
                    break
                end
            end
            if not isValid then
                table.insert(toRemove, cacheKey)
            end
        end
    end
    for _, key in ipairs(toRemove) do
        config.varibz.sa2dump.data[key] = nil
    end
    table.clear(toRemove)
    local wallToRemove = toRemove
    for cacheKey in pairs(config.varibz.sa2dump.cache) do
        local playerId = cacheKey:match("player_(%d+)")
        if playerId then
            playerId = tonumber(playerId)
            local isValid = false
            for p, valid in pairs(validPlayers) do
                if p and p.UserId == playerId and valid == true then
                    isValid = true
                    break
                end
            end
            if not isValid then
                table.insert(wallToRemove, cacheKey)
            end
        end
    end
    for _, key in ipairs(wallToRemove) do
        config.varibz.sa2dump.cache[key] = nil
    end
    table.clear(wallToRemove)
    if bestTarget then
        if seenMode and bestTarget ~= config.SA2_currentTarget then
            if shouldSwitch or not config.SA2_currentTarget then
                config.lastTargetSwitchTime = currentTime
                config.SA2_currentTarget = bestTarget
            else
                local currentStillValid = false
                for p in pairs(seenTargets) do
                    if p == config.SA2_currentTarget then
                        currentStillValid = true
                        break
                    end
                end
                if not currentStillValid then
                    config.SA2_currentTarget = bestTarget
                    config.lastTargetSwitchTime = currentTime
                end
            end
        else
            config.SA2_currentTarget = bestTarget
        end
        local char = getTargetCharacter(bestTarget)
        if char then
            local part = char:FindFirstChild(config.SA2_TargetPart)
            if not part then
                part = char:FindFirstChild("Head")
            end
            if not part then
                part = char:FindFirstChild("HumanoidRootPart")
            end
            if part then
                updateESPColors()
                return part
            end
        end
    else
        config.SA2_currentTarget = nil
        return nil
    end
    return nil
end
excusemesir.RunService.Heartbeat:Connect(function(deltaTime)
    if not config.varibz.patcher then
        return
    end
    config.varibz.sa2thing += deltaTime
    config.varibz.sa2alot = config.varibz.sa2alot + 1
    if config.varibz.sa2thing >= config.varibz.sa2stuff and config.varibz.sa2alot % 2 == 0 then
        config.varibz.sa2thing = 0
        if config.SA2_Enabled then
            config.varibz.sa2this = true
            folkenstein______ = GetClosestPlayer()
            config.varibz.sa2this = false
            if folkenstein______ then
                config.varibz.sa2LockUntil = tick() + math.max(0.3, (config.varibz.sa2stuff or 0.5) * 1.5)
            end
        end
    end
end)

local function predictthatpos(targetPart, velocityOverride)
    if not targetPart or not targetPart.Parent then
        return targetPart and targetPart.Position or nil
    end

    local pos = targetPart.Position
    local predTime = tonumber(config.SA2_Prediction) or 0
    if predTime <= 0 then
        return pos
    end
    if predTime > 0.5 then
        predTime = 0.5
    end
    return pos + ((velocityOverride or targetPart.Velocity) * predTime)
end


