function espRefresher()
    if not config.espMasterEnabled then 
        for target, _ in pairs(config.espData) do
            removeESPLabel(target)
        end
        for target, _ in pairs(config.highlightData) do
            removeHighlightESP(target)
        end
        for target, _ in pairs(config.lineESPData) do
            removeLineESP(target)
        end
        config.espData = {}
        config.highlightData = {}
        config.lineESPData = {}
        return 
    end
    
    local validTargets = {}
    for _, target in ipairs(getAllTargets()) do
        if addesp(target) and plralive(target) then
            validTargets[target] = true
            if (config.prefTextESP or config.prefBoxESP or config.prefHealthESP or config.prefHeadDotESP) 
               and not config.espData[target] then
                makeesp(target)
            end
            if config.prefHighlightESP and not config.highlightData[target] then
                high(target)
            end
            if config.lineESPEnabled and not config.lineESPData[target] then
                createLineESP(target)
            end
        end
    end
    for target, _ in pairs(config.espData) do
        if not validTargets[target] then
            removeESPLabel(target)
        end
    end
    for target, _ in pairs(config.highlightData) do
        if not validTargets[target] then
            removeHighlightESP(target)
        end
    end
    for target, _ in pairs(config.lineESPData) do
        if not validTargets[target] then
            removeLineESP(target)
        end
    end
    updateESPColors()
end
end
local chooseBodyPartInstance, applySizeToPart, expandhb, updateeveryproxyeva, hb
do

function chooseBodyPartInstance(target)
    local char = getTargetCharacter(target)
    if not char then return nil, "Head" end

    local bp = config.bodypart or "Head"

    if bp == "Head" then
        return char:FindFirstChild("Head"), "Head"
    elseif bp == "HumanoidRootPart" then
        return char:FindFirstChild("HumanoidRootPart"), "HumanoidRootPart"
    elseif bp == "Random" then
        config._selectedPartForTarget = config._selectedPartForTarget or {}
        if config._selectedPartForTarget[target] then
            local selectedName = config._selectedPartForTarget[target]
            local part = char:FindFirstChild(selectedName)
            if part then
                return part, selectedName
            end
        end
        local selectedPart = nil
        local selectedName = "Head"
        
        if math.random(1, 100) <= config.sa_hb_headshot_chance then
            local head = char:FindFirstChild("Head")
            if head then
                selectedPart = head
                selectedName = "Head"
            end
        end
        if not selectedPart then
            local rootPart = char:FindFirstChild("HumanoidRootPart")
            if rootPart then
                selectedPart = rootPart
                selectedName = "HumanoidRootPart"
            end
        end
        if not selectedPart then
            local head = char:FindFirstChild("Head")
            selectedPart = head
            selectedName = (head and head.Name) or "Head"
        end
        config._selectedPartForTarget[target] = selectedName
        return selectedPart, selectedName
    else
        local found = char:FindFirstChild(bp) or char:FindFirstChild("Head")
        return found, (found and found.Name) or "Head"
    end
end
function applySizeToPart(targetPlayer, targetDiameter, chosenPart)
    local char = getTargetCharacter(targetPlayer)
    if not char or targetPlayer == localPlayer then return end
    if not plralive(targetPlayer) then return end
    local part = chosenPart
    local partName = nil
    if not part then
        part, partName = chooseBodyPartInstance(targetPlayer)
    else
        partName = part.Name
    end

    if not part or not part.Parent then return end
    if config.hitboxEnabled then
        local pName = part.Name
        if pName == "Torso" or pName == "UpperTorso" or pName == "LowerTorso" then
            local fallback = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
            if not fallback then return end
            if fallback.Name == "Torso" or fallback.Name == "UpperTorso" or fallback.Name == "LowerTorso" then
                return
            end
            part = fallback
            partName = part.Name
            if config.originalSizes[targetPlayer] and
               (config.originalSizes[targetPlayer].partName == "Torso" or
                config.originalSizes[targetPlayer].partName == "UpperTorso" or
                config.originalSizes[targetPlayer].partName == "LowerTorso") then
                config.originalSizes[targetPlayer].partName = part.Name
                config.originalSizes[targetPlayer].size = part.Size
            end
        end
    end
    if not config.originalSizes[targetPlayer] then
        config.originalSizes[targetPlayer] = {
            partName = part.Name,
            size = part.Size,
        }
    end
    if config._selectedPartForTarget and config._selectedPartForTarget[targetPlayer] then
        local expectedPart = config._selectedPartForTarget[targetPlayer]
        if part.Name ~= expectedPart then
            local correctPart = char:FindFirstChild(expectedPart)
            if correctPart and correctPart.Parent then
                if not (config.hitboxEnabled and
                       (correctPart.Name == "Torso" or
                        correctPart.Name == "UpperTorso" or
                        correctPart.Name == "LowerTorso")) then
                    part = correctPart
                    partName = expectedPart
                end
            end
        end
    end
    if not part or not part.Parent then return end
    local expansionSize = Vector3.new(
        targetDiameter,
        targetDiameter,
        targetDiameter
    )

    if config.scaleToScreen then
        local localChar = localPlayer.Character
        if localChar then
            local localRoot = localChar:FindFirstChild("HumanoidRootPart") or localChar:FindFirstChild("Head")
            if localRoot then
                local targetPartPos = part.Position
                local localPos = localRoot.Position
                local distance = (targetPartPos - localPos).Magnitude
                local viewportSize = camera.ViewportSize
                local fov = camera.FieldOfView
                local screenHeight = viewportSize.Y
                local safeDistance = math.max(config.stsdistance, 0.1)
                local effectiveDistance = math.max(distance - safeDistance, 0.1)
                local screenCoverSize = (effectiveDistance * math.tan(math.rad(fov / 2))) * 2
                expansionSize = Vector3.new(
                    math.max(screenCoverSize, targetDiameter),
                    math.max(screenCoverSize, targetDiameter),
                    math.max(screenCoverSize, targetDiameter)
                )
            end
        end
    end
    local useExpanded = true
    local chance = math.clamp(tonumber(config.hitchance) or 100, 0, 100)
    if chance <= 0 then
        useExpanded = false
    elseif chance < 100 then
        if math.random(1, 100) <= chance then
            useExpanded = true
        else
            useExpanded = false
        end
    else
        useExpanded = true
    end
    if useExpanded then
        config.targethbSizes[targetPlayer] = expansionSize
    else
        local original = config.originalSizes[targetPlayer]
        if original and original.size then
            config.targethbSizes[targetPlayer] = original.size
        else
            config.targethbSizes[targetPlayer] = part.Size
        end
    end
    config.activeApplied[targetPlayer] = true
    local targetSize = config.targethbSizes[targetPlayer]
    if targetSize and typeof(targetSize) == "Vector3" and part and part.Parent then
        part.Size = targetSize
        part.Transparency = config.hbtrans or 0.5
        part.CanCollide = false
        if part.Name == "Head" then
            part.Massless = true
            part.CanCollide = false
        elseif part.Name == "HumanoidRootPart" then
            part.Massless = false
            part.CanCollide = false
        end
    else
        config.targethbSizes[targetPlayer] = nil
        config.activeApplied[targetPlayer] = nil
    end
end
function restorePartForPlayer(targetPlayer)
    if not targetPlayer or targetPlayer == localPlayer then return end
    local char = getTargetCharacter(targetPlayer)
    local original = config.originalSizes[targetPlayer]
    if original and original.size then
        local part = nil
        if char then
            if original.partName then
                part = char:FindFirstChild(original.partName)
            end
            if not part then
                part = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
            end
        end

        if part and part.Parent then
            part.Size = original.size
            if part.Name == "HumanoidRootPart" then
                part.Transparency = 1
                part.Massless = false
            else
                part.Transparency = 0
                part.Massless = true
            end
            part.CanCollide = false
            if part:IsA("BasePart") then
                part.Velocity = Vector3.new(0, 0, 0)
                part.RotVelocity = Vector3.new(0, 0, 0)
            end
        end
    end
    config.activeApplied[targetPlayer] = nil
    config.originalSizes[targetPlayer] = nil
    config.targethbSizes[targetPlayer] = nil
    config.centerLocked[targetPlayer] = nil
    if config._selectedPartForTarget then
        config._selectedPartForTarget[targetPlayer] = nil
    end
end
local function proxyhb(targetPlayer)
    if not targetPlayer then return nil end
    if targetPlayer == localPlayer then return nil end
    local char = getTargetCharacter(targetPlayer)
    if not char then return nil end
    local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
    if not torso then return nil end
    if config.proxyHitboxes[targetPlayer] then
        config.proxyHitboxes[targetPlayer]:Destroy()
        config.proxyHitboxes[targetPlayer] = nil
    end
    
    local proxyPart = Instance.new("Part")
    proxyPart.Name = "3827636473772_83737377_339_" .. tostring(math.random(10000, 99999))
    proxyPart.Anchored = false
    proxyPart.CanCollide = false
    proxyPart.Massless = true
    proxyPart.CastShadow = false
    proxyPart.Transparency = config.hitboxVisualizer.transparency or 0.5
    proxyPart.Color = config.hitboxVisualizer.color or Color3.fromRGB(255, 0, 0)
    local gap = config.hitboxVisualizer.gap or 0.4
    local baseSize = torso.Size
    local proxySize = Vector3.new(
        math.max(baseSize.X - gap, 0.1),
        math.max(baseSize.Y - gap, 0.1),
        math.max(baseSize.Z - gap, 0.1)
    )
    proxyPart.Size = proxySize
    
    proxyPart.Material = config.materials[config.hitboxVisualizer.material] or Enum.Material.Neon
    if config.hitboxVisualizer.shape == "Sphere" then
        proxyPart.Shape = Enum.PartType.Ball
    else
        proxyPart.Shape = Enum.PartType.Block
    end
    
    proxyPart.Parent = workspace
    config.proxyHitboxes[targetPlayer] = proxyPart
    local weld = Instance.new("Weld")
    weld.Name = "ProxyWeld"
    weld.Part0 = proxyPart
    weld.Part1 = torso
    weld.C0 = CFrame.new(0, 0, 0)
    weld.Parent = proxyPart
    
    return proxyPart
end

local function tnormalsize(targetPlayer)
    local char = getTargetCharacter(targetPlayer)
    if not char then return end  

    local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")

    if torso and not config.hitboxOriginalSizes[targetPlayer] then
        config.hitboxOriginalSizes[targetPlayer] = {
            part = torso,
            size = torso.Size
        }
    end
end

function updateproxyhb(targetPlayer)
    if not targetPlayer then return end
    if not config.hitboxVisualizer.enabled then
        if config.proxyHitboxes[targetPlayer] then
            config.proxyHitboxes[targetPlayer]:Destroy()
            config.proxyHitboxes[targetPlayer] = nil
        end
        return
    end
    
    local char = getTargetCharacter(targetPlayer)
    if not char then return end
    local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
    if not torso then return end
    local proxyPart = config.proxyHitboxes[targetPlayer]
    if not proxyPart or not proxyPart.Parent then
        proxyPart = proxyhb(targetPlayer)
        if not proxyPart then return end
    end
    
    local hitboxSize = config.hitboxSize or 10
    local actualSize = Vector3.new(hitboxSize, hitboxSize, hitboxSize)
    local gap = config.hitboxVisualizer.gap or 0.4
    local proxySize = Vector3.new(
        math.max(actualSize.X - gap, 0.1),
        math.max(actualSize.Y - gap, 0.1),
        math.max(actualSize.Z - gap, 0.1)
    )
    
    proxyPart.Size = proxySize
    proxyPart.Transparency = config.hitboxVisualizer.transparency or 0.5
    proxyPart.Color = config.hitboxVisualizer.color or Color3.fromRGB(255, 0, 0)
    proxyPart.Material = config.materials[config.hitboxVisualizer.material] or Enum.Material.Neon
    if config.hitboxVisualizer.shape == "Sphere" then
        proxyPart.Shape = Enum.PartType.Ball
    else
        proxyPart.Shape = Enum.PartType.Block
    end
end

function expandhb(targetPlayer, size)
    if not targetPlayer then return end
    if targetPlayer == localPlayer then return end
    if not plralive(targetPlayer) then return end  
    
    if not config.hitboxEnabled then 
        restoreTorso(targetPlayer)
        if config.proxyHitboxes[targetPlayer] then
            config.proxyHitboxes[targetPlayer]:Destroy()
            config.proxyHitboxes[targetPlayer] = nil
        end
        return 
    end

    local char = getTargetCharacter(targetPlayer)
    if not char then return end
    local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")  
    if not torso then return end  

    tnormalsize(targetPlayer)
    local expansionSize = Vector3.new(size, size, size)
    config.hitboxLastSize[targetPlayer] = size

    config.hitboxExpandedParts[targetPlayer] = {
        part = torso,
        targetSize = expansionSize,
        originalSize = config.hitboxOriginalSizes[targetPlayer] and config.hitboxOriginalSizes[targetPlayer].size or torso.Size
    }
    
    if config.hitboxEnabled then
        pcall(function()
            torso.Size = expansionSize
            if config.hitboxVisualizer.enabled then
                torso.Transparency = 1
            else
                torso.Transparency = 1
            end
            torso.CanCollide = false
            torso.Massless = true
            if config.hitboxColor then
                torso.Color = config.hitboxColor
            else
                torso.Color = Color3.fromRGB(255, 255, 255)
            end
        end)
        if config.hitboxVisualizer.enabled then
            updateproxyhb(targetPlayer)
        end
    end
end

function restoreTorso(targetPlayer)
    if not targetPlayer then return end  

    local original = config.hitboxOriginalSizes[targetPlayer]
    if original and original.part and original.part.Parent then
        pcall(function()
            original.part.Size = original.size
            original.part.Transparency = 0
            original.part.CanCollide = false
        end)
    end

    config.hitboxExpandedParts[targetPlayer] = nil
    config.hitboxOriginalSizes[targetPlayer] = nil
    if config.proxyHitboxes[targetPlayer] then
        config.proxyHitboxes[targetPlayer]:Destroy()
        config.proxyHitboxes[targetPlayer] = nil
    end
end

local function updateHitboxes()
    if not config.hitboxEnabled then
        for player, _ in pairs(config.hitboxExpandedParts) do  
            table.insert(config.varibz.targetsToRemove, player)
        end
        for _, player in ipairs(config.varibz.targetsToRemove) do
            restoreTorso(player)
        end
        
        if config.hitboxVisualizer.enabled then
            for player, proxy in pairs(config.proxyHitboxes) do
                if proxy and proxy.Parent then
                    proxy:Destroy()
                end
            end
            config.proxyHitboxes = {}
        end
        return  
    end
    for player, data in pairs(config.hitboxExpandedParts) do
        if not player or not getTargetCharacter(player) then
            table.insert(config.varibz.targetsToRemove, player)
        else
            if not plralive(player) then
                restoreTorso(player)
                table.insert(config.varibz.targetsToRemove, player)
            else
                local torso = getTargetCharacter(player):FindFirstChild("Torso") or getTargetCharacter(player):FindFirstChild("UpperTorso")
                if torso and data.targetSize then
                    pcall(function()
                        torso.Size = data.targetSize
                        if config.hitboxVisualizer.enabled then
                            torso.Transparency = 1
                        else
                            torso.Transparency = 1
                        end
                        torso.CanCollide = false
                        torso.Massless = true
                    end)
                    
                    if config.hitboxVisualizer.enabled then
                        updateproxyhb(player)
                    end
                else
                    table.insert(config.varibz.targetsToRemove, player)
                end
            end
        end
    end
    
    for _, player in ipairs(config.varibz.targetsToRemove) do
        restoreTorso(player)
        if config.proxyHitboxes[player] then
            config.proxyHitboxes[player]:Destroy()
            config.proxyHitboxes[player] = nil
        end
    end
end

function targethb(player)
    if not player or player == localPlayer then return false end  
    if not plralive(player) then return false end  
    local char = getTargetCharacter(player)
    if config.ignoreForcefield and char and hasForcefield(char) then return false end
    if config.specificTeamTarget and #config.targetedTeams > 0 then
        if typeof(player) == "Instance" and player:IsA("Player") then
            local team = player.Team
            if team then
                for _, teamName in ipairs(config.targetedTeams) do
                    if team.Name == teamName then
                        return true
                    end
                end
            end
            return false
        end
        if typeof(player) == "Instance" and player:IsA("Model") then
            local npcTeam = player:FindFirstChild("Team")
            if npcTeam and npcTeam:IsA("ObjectValue") and npcTeam.Value then
                for _, teamName in ipairs(config.targetedTeams) do
                    if npcTeam.Value.Name == teamName then
                        return true
                    end
                end
            end
            return false
        end
        return false
    end
    local mode = config.masterTeamTarget or "Enemies"
    if typeof(player) == "Instance" and player:IsA("Model") then
        if mode == "Teams" then
            return false
        end
        return true
    end

    if mode == "Enemies" then
        return not isTeammate(player)
    elseif mode == "Teams" then
        return isTeammate(player)
    elseif mode == "All" then
        return true
    end

    return false
end

