function jsnwekixuzjakwio_textnsiehne_()
    if not config.TextHooker or type(config.TextHooker) ~= "table" then return end
    if next(config.TextHooker) == nil then return end
    local CoreGui = excusemesir.CoreGui
    local hookPairs = {}
    for from, to in pairs(config.TextHooker) do
        if type(from) == "string" and type(to) == "string" and from ~= "" then
            table.insert(hookPairs, { exact = from, exactTo = to })
        end
    end
    if #hookPairs == 0 then return end

    local function applyHooks(txt)
        if not txt or txt == "" then return txt end
        for _, pair in ipairs(hookPairs) do
            if txt == pair.exact then
                return pair.exactTo
            end
        end
        return txt
    end
    local labels = {}
    local boxes = {}
    local inRegistry = setmetatable({}, { __mode = "k" })
    local seenText = setmetatable({}, { __mode = "k" })
    local seenPlaceholder = setmetatable({}, { __mode = "k" })
    local function register(obj)
        if not obj or inRegistry[obj] then return end
        if obj:IsA("TextBox") then
            inRegistry[obj] = true
            table.insert(boxes, obj)
        elseif obj:IsA("TextLabel") or obj:IsA("TextButton") then
            inRegistry[obj] = true
            table.insert(labels, obj)
        end
    end
    for _, d in ipairs(CoreGui:GetDescendants()) do
        register(d)
    end
    local function processLabel(obj)
        if not obj or not obj.Parent then return end
        local txt = obj.Text
        if not txt or txt == "" then return end
        if seenText[obj] == txt then return end
        local newText = applyHooks(txt)
        if newText ~= txt then
            seenText[obj] = newText
            obj.Text = newText
        else
            seenText[obj] = txt
        end
    end

    local function processBox(obj)
        if not obj or not obj.Parent then return end
        local txt = obj.Text
        if txt and txt ~= "" and seenText[obj] ~= txt then
            local newText = applyHooks(txt)
            if newText ~= txt then
                seenText[obj] = newText
                obj.Text = newText
            else
                seenText[obj] = txt
            end
        end
        local ph = obj.PlaceholderText
        if ph and ph ~= "" and seenPlaceholder[obj] ~= ph then
            local newPh = applyHooks(ph)
            if newPh ~= ph then
                seenPlaceholder[obj] = newPh
                obj.PlaceholderText = newPh
            else
                seenPlaceholder[obj] = ph
            end
        end
    end
    local function processAll()
        for i = #labels, 1, -1 do
            local obj = labels[i]
            if not obj or not obj.Parent then
                inRegistry[obj] = nil
                table.remove(labels, i)
            else
                processLabel(obj)
            end
        end
        for i = #boxes, 1, -1 do
            local obj = boxes[i]
            if not obj or not obj.Parent then
                inRegistry[obj] = nil
                table.remove(boxes, i)
            else
                processBox(obj)
            end
        end
    end
    local descendantConn = CoreGui.DescendantAdded:Connect(function(d)
        if not d then return end
        if d:IsA("TextBox") or d:IsA("TextLabel") or d:IsA("TextButton") then
            register(d)
            if d:IsA("TextBox") then
                processBox(d)
            else
                processLabel(d)
            end
        end
    end)

    config.TextHookerRunning = true
    config.TextHookerConnection = descendantConn

    task_("textHookerLoop", function()
        while config.TextHookerRunning do
            if subside_I_I_I_I_I_() then
                task.wait(0.5)
                continue
            end
            processAll()
            task.wait(0.25)
        end
    end)
end
-- bgupdater
local function burgerking(deltaTime)
    if not config.varibz.patcher then
        return
    end
    if config.aimbotEnabled then
        config.varibz.aimbotdump.accum = (config.varibz.aimbotdump.accum or 0) + deltaTime
        local interval = 1 / math.max(config.aimhertz or 100, 1)
        if config.varibz.aimbotdump.accum >= interval then
            config.varibz.aimbotdump.accum = 0
            aimbotUpdate()
        end
    end
    updateLineESP()
    if config.hitboxEnabled then
        hb()
    end
    if config.SA2_Enabled then
        local currentTime = tick()
        local vz = config.varibz
        if not vz.sa2FindToolBusy and currentTime - (vz.sa2FindToolLast or 0) >= 1 then
            vz.sa2FindToolLast = currentTime
            vz.sa2FindToolBusy = true
            task.spawn(function()
                pcall(function()
                    if not vz.sa2FindToolFn then
                        local src = getgist_(getgenv().HttpUrlz_.sa2findtool)
                        if src then vz.sa2FindToolFn = loadstring(src) end
                    end
                    if vz.sa2FindToolFn then vz.sa2FindToolFn() end
                end)
                vz.sa2FindToolBusy = false
            end)
        end
    end
    if config.antiAimEnabled then
        antiAimUpdate()
    end
    if config.worldXrayEnabled then
        if config.varibz.xraystuff == nil then
            config.varibz.xraystuff = config.masterTarget
        elseif config.masterTarget ~= config.varibz.xraystuff then
            config.varibz.xraystuff = config.masterTarget
            RestoreXray()
            config.worldXrayOriginalValues = {}
            ApplyXray()
            if config.worldXrayConnection then
                config.worldXrayConnection:Disconnect()
            end
            config.worldXrayConnection = workspace.DescendantAdded:Connect(function(obj)
                if config.worldXrayEnabled and obj:IsA("BasePart") and not obj:IsA("Terrain") and ShouldXrayPart(obj) then
                    if not config.worldXrayOriginalValues[obj] then
                        config.worldXrayOriginalValues[obj] = obj.Transparency
                    end
                    obj.Transparency = config.worldXrayTransparency or 0.5
                end
            end)
        end
    else
        config.varibz.xraystuff = config.masterTarget
    end
end
task_("espColorLoop", function()
    while config.espMasterEnabled do
        updateESPColors()
        task.wait(math.max(1 / math.max(config.esphertz or 100, 1), 0.05))
    end
end)
heartbeatConnection = excusemesir.RunService.Heartbeat:Connect(burgerking)
end
