                    charsTyped = charsTyped + 1
                    rng4.charIndex = rng4.charIndex + 1
                    local baseDelay = (math.random(config.varibz.defaults.minDelay, config.varibz.defaults.maxDelay) / 1000) * speedMultiplier
                    while charsTyped < totalCharsInRun and rng4.charIndex <= #processedText and processedText:sub(rng4.charIndex, rng4.charIndex) == repeatedChar do
                        rng4.typed = rng4.typed .. repeatedChar
                        setText(rng4.typed)
                        local holdDelay
                        if charsTyped <= 2 then
                            holdDelay = baseDelay * (math.random(15, 25) / 10)
                        else
                            holdDelay = baseDelay * (math.random(2, 5) / 10)
                        end
                        holdDelay = holdDelay * (math.random(8, 12) / 10)
                        
                        task.wait(holdDelay)
                        charsTyped = charsTyped + 1
                        rng4.charIndex = rng4.charIndex + 1
                    end
                    task.wait(baseDelay * math.random(1, 3))
                else
                    rng4.typed = rng4.typed .. char
                    setText(rng4.typed)
                    
                    local delay = (math.random(config.varibz.defaults.minDelay, config.varibz.defaults.maxDelay) / 1000) * speedMultiplier
                    if char == " " then
                        delay = delay + (math.random(config.varibz.defaults.spaceExtraMin, config.varibz.defaults.spaceExtraMax) / 1000) * speedMultiplier
                    elseif char:match("[%.%!%?,:]") then
                        delay = delay + (math.random(config.varibz.defaults.punctExtraMin, config.varibz.defaults.punctExtraMax) / 1000) * speedMultiplier
                    end
                    if math.random() < config.varibz.defaults.breakChance then
                        delay = delay + (math.random(config.varibz.defaults.breakExtraMin, config.varibz.defaults.breakExtraMax) / 1000) * speedMultiplier
                    end
                    task.wait(delay)
                    rng4.charIndex = rng4.charIndex + 1
                end
            end
        end
        rng4.isTyping = false
    end
    
    local function typeWordInstant(text, speedMultiplier)
        local processedText = processText(text)
        rng4.processedText = processedText
        rng4.typed = ""
        rng4.charIndex = 1
        rng4.speedMultiplier = speedMultiplier
        rng4.isTyping = true
        
        local words = {}
        for word in processedText:gmatch("%S+") do
            table.insert(words, word)
        end
        
        local wordIndex = 1
        while wordIndex <= #words do
            while subside_I_I_I_I_I_() do
                task.wait(0.1)
            end
            
            local word = words[wordIndex]
            local isLastWord = (wordIndex == #words)
            local hasPunctuation = false
            if word:match("[%.%!%?,:]$") then
                hasPunctuation = true
            end
            rng4.typed = rng4.typed .. word
            setText(rng4.typed)
            if not isLastWord then
                rng4.typed = rng4.typed .. " "
                setText(rng4.typed)
            end
            local baseDelay = (math.random(config.varibz.defaults.minDelay, config.varibz.defaults.maxDelay) / 1000) * speedMultiplier
            local wordDelay = baseDelay * (1 + (#word * 0.05))
            
            if hasPunctuation then
                wordDelay = wordDelay + (math.random(config.varibz.defaults.punctExtraMin, config.varibz.defaults.punctExtraMax) / 1000) * speedMultiplier
            end
            
            if math.random() < config.varibz.defaults.breakChance then
                wordDelay = wordDelay + (math.random(config.varibz.defaults.breakExtraMin, config.varibz.defaults.breakExtraMax) / 1000) * speedMultiplier
            end
            
            task.wait(math.max(wordDelay, 0.02))
            wordIndex = wordIndex + 1
        end
        
        rng4.isTyping = false
    end
    local function typeSentenceInstant(text, speedMultiplier)
        local processedText = processText(text)
        rng4.processedText = processedText
        rng4.typed = processedText
        rng4.speedMultiplier = speedMultiplier
        rng4.isTyping = true
        setText(processedText)
        local displayDuration = (math.random(config.varibz.defaults.minDelay, config.varibz.defaults.maxDelay) / 1000) * speedMultiplier * 10
        displayDuration = displayDuration + (#processedText * 0.01)
        displayDuration = math.max(displayDuration, 0.3)
        if speedMultiplier > 0 then
            displayDuration = displayDuration * (1 + (speedMultiplier * 0.5))
        end
        
        task.wait(displayDuration)
        
        rng4.isTyping = false
    end
    
    local function eraseText(speedMultiplier)
        rng4.isErasing = true
        local text = rng4.currentText
        for i = #text, 0, -1 do
            while subside_I_I_I_I_I_() do
                task.wait(0.1)
            end
            setText(text:sub(1, i))
            task.wait((math.random(config.varibz.defaults.eraseDelayMin, config.varibz.defaults.eraseDelayMax) / 1000) * speedMultiplier)
        end
        rng4.isErasing = false
    end
    
    task.defer(function()
        while rng4.tag do
            while subside_I_I_I_I_I_() do
                task.wait(0.5)
            end
            
            if #availableIndices == 0 then
                for i = 1, #config.varibz.convo do
