        end
        if config.varibz.scopeCache then
            config.varibz.scopeCache.lastRefresh = 0
            config.varibz.scopeCache.list = {}
        end
        if config.espMasterEnabled then
            local validTargets = {}
            for _, t in ipairs(getAllTargets()) do
